<script setup>
import { ref, computed, onMounted } from 'vue'
import { Plus, Search, ArrowLeft, ArrowRight, Calendar, Position, ChatDotRound, Edit, Delete, Clock } from '@element-plus/icons-vue'
import api from '../api'

const events = ref([])

const viewMode = ref('month')
const currentDate = ref(new Date())
const searchKeyword = ref('')
const createEventVisible = ref(false)
const viewEventVisible = ref(false)
const selectedEvent = ref(null)
const isEditing = ref(false)

const newEvent = ref({
  title: '',
  type: '',
  startTime: new Date(),
  endTime: new Date(),
  location: '',
  description: ''
})

const weekdays = ['日', '一', '二', '三', '四', '五', '六']

onMounted(async () => {
  try {
    const response = await api.getEvents()
    events.value = response.data.map(event => ({
      ...event,
      startTime: new Date(event.start_time),
      endTime: new Date(event.end_time)
    }))
  } catch (error) {
    console.error('获取日程失败:', error)
  }
})

const currentPeriodText = computed(() => {
  if (viewMode.value === 'month') {
    return currentDate.value.toLocaleDateString('zh-CN', { year: 'numeric', month: 'long' })
  } else if (viewMode.value === 'week') {
    const start = new Date(currentDate.value)
    const day = start.getDay() || 7
    start.setDate(start.getDate() - day + 1)
    const end = new Date(start)
    end.setDate(end.getDate() + 6)
    return `${start.toLocaleDateString('zh-CN')} - ${end.toLocaleDateString('zh-CN')}`
  } else {
    return currentDate.value.toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' })
  }
})

const currentDateText = computed(() => {
  return currentDate.value.toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' })
})

const monthDays = computed(() => {
  const year = currentDate.value.getFullYear()
  const month = currentDate.value.getMonth()
  const firstDay = new Date(year, month, 1)
  const lastDay = new Date(year, month + 1, 0)
  const startDate = new Date(firstDay)
  startDate.setDate(startDate.getDate() - firstDay.getDay())
  const days = []
  for (let i = 0; i < 42; i++) {
    const date = new Date(startDate)
    date.setDate(startDate.getDate() + i)
    const isCurrentMonth = date.getMonth() === month
    const isToday = date.toDateString() === new Date().toDateString()
    days.push({
      date: date,
      day: date.getDate(),
      isCurrentMonth: isCurrentMonth,
      isToday: isToday
    })
  }
  return days
})

const weekDays = computed(() => {
  const days = []
  const start = new Date(currentDate.value)
  const day = start.getDay() || 7
  start.setDate(start.getDate() - day + 1)
  for (let i = 0; i < 7; i++) {
    const date = new Date(start)
    date.setDate(start.getDate() + i)
    days.push({
      date: date,
      day: date.getDate(),
      dayName: weekdays[date.getDay()],
      isToday: date.toDateString() === new Date().toDateString()
    })
  }
  return days
})

const upcomingEvents = computed(() => {
  return events.value
    .filter(event => {
      const searchMatch = !searchKeyword.value || 
        event.title.includes(searchKeyword.value) || 
        event.description.includes(searchKeyword.value)
      return searchMatch
    })
    .sort((a, b) => new Date(a.startTime) - new Date(b.startTime))
    .slice(0, 6)
})

const selectedDateEvents = computed(() => {
  return getDayEvents(currentDate.value).slice().sort((a, b) => new Date(a.startTime) - new Date(b.startTime))
})

const getDayEvents = (date) => {
  const dateStr = date.toDateString()
  return events.value.filter(event => {
    const eventDate = new Date(event.startTime).toDateString()
    return eventDate === dateStr
  })
}

const getHourEvents = (hour) => {
  const dateStr = currentDate.value.toDateString()
  return events.value.filter(event => {
    const eventDate = new Date(event.startTime)
    const eventDateStr = eventDate.toDateString()
    const eventHour = eventDate.getHours()
    return eventDateStr === dateStr && eventHour === hour
  })
}

const getEventTypeText = (type) => {
  const typeMap = { meeting: '会议', equipment: '设备使用', experiment: '实验', other: '其他' }
  return typeMap[type] || type
}

const getEventTypeTagType = (type) => {
  const typeMap = { meeting: '', equipment: 'warning', experiment: 'danger', other: 'success' }
  return typeMap[type] || ''
}

const formatEventTime = (event) => {
  const start = new Date(event.startTime)
  return start.toLocaleDateString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' })
}

const formatTime = (date) => {
  return new Date(date).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })
}

const formatEventTimeRange = (event) => {
  const start = new Date(event.startTime)
  const end = new Date(event.endTime)
  return `${start.toLocaleString('zh-CN')} - ${end.toLocaleString('zh-CN')}`
}

const prevPeriod = () => {
  if (viewMode.value === 'month') {
    currentDate.value = new Date(currentDate.value.getFullYear(), currentDate.value.getMonth() - 1, 1)
  } else if (viewMode.value === 'week') {
    currentDate.value = new Date(currentDate.value.getFullYear(), currentDate.value.getMonth(), currentDate.value.getDate() - 7)
  } else {
    currentDate.value = new Date(currentDate.value.getFullYear(), currentDate.value.getMonth(), currentDate.value.getDate() - 1)
  }
}

const nextPeriod = () => {
  if (viewMode.value === 'month') {
    currentDate.value = new Date(currentDate.value.getFullYear(), currentDate.value.getMonth() + 1, 1)
  } else if (viewMode.value === 'week') {
    currentDate.value = new Date(currentDate.value.getFullYear(), currentDate.value.getMonth(), currentDate.value.getDate() + 7)
  } else {
    currentDate.value = new Date(currentDate.value.getFullYear(), currentDate.value.getMonth(), currentDate.value.getDate() + 1)
  }
}

const selectDate = (date) => {
  currentDate.value = date
  viewMode.value = 'day'
}

const openCreateEventDialog = () => {
  isEditing.value = false
  newEvent.value = {
    title: '',
    type: '',
    startTime: new Date(),
    endTime: new Date(),
    location: '',
    description: ''
  }
  createEventVisible.value = true
}

const editEvent = (event) => {
  isEditing.value = true
  newEvent.value = JSON.parse(JSON.stringify(event))
  createEventVisible.value = true
}

const saveEvent = () => {
  if (newEvent.value.title && newEvent.value.type && newEvent.value.startTime && newEvent.value.endTime) {
    if (isEditing.value) {
      const index = events.value.findIndex(e => e.id === newEvent.value.id)
      if (index !== -1) {
        events.value[index] = { ...newEvent.value }
      }
    } else {
      const event = { id: Date.now().toString(), ...newEvent.value }
      events.value.push(event)
    }
    createEventVisible.value = false
  }
}

const viewEvent = (event) => {
  selectedEvent.value = JSON.parse(JSON.stringify(event))
  viewEventVisible.value = true
}

const deleteEvent = (id) => {
  console.log('删除日程:', id)
}
</script>

